import React from 'react'
import ReactDOM from 'react-dom/client'
import PrivacyPage from './components/PrivacyPage'
import { initAnalytics } from './lib/analytics'
import './index.css'

// Entry for /privacy-policy/. The HTML is generated by scripts/generate-pages.mjs
// and pre-rendered at build time, so it is hydrated rather than rendered from scratch.
const root = document.getElementById('root')
const tree = (
  <React.StrictMode>
    <PrivacyPage />
  </React.StrictMode>
)
if (root.hasChildNodes()) ReactDOM.hydrateRoot(root, tree)
else ReactDOM.createRoot(root).render(tree)

// Google Analytics: production host only, and only after consent.
initAnalytics()
